WFJ.Data.add("spell", {
  [431046] = { "Quando impugni armi a $N1 mani, la tua velocità d'attacco aumenta del $N2%.", nil, 0xe8e8d27a, nil, "um" },
  [431388] = { "Pelledura ora può essere lanciata sugli alleati, non penalizza più la velocità di combattimento in mischia né il tempo di lancio degli incantesimi e può essere lanciata in forma trasformata.", nil, 0x1138f0e7, nil, "um" },
  [431389] = { "⟦Frenzied Regeneration=Rigenerazione Furiosa⟧ ora può essere usata in tutte le forme tranne ⟦Moonkin Form=Forma di Lunagufo⟧ e la forma normale. Ora converte la tua risorsa attiva in salute ogni secondo per $D1. Ogni secondo vengono convertiti fino a $N2 rabbia, $N3 energia o il $N4% del mana di base in fino al $N5% di salute.", nil, 0x144ef7d3, nil, "um" },
  [431446] = { "Ottieni l'abilità Sbudellamento:\n\n$I1\nColpire un bersaglio con Lacerazione, Spazzata o Zampata ha una probabilità del $N1% di azzerare il tempo di recupero di Mangle (Bear) e di fornire $N2 rabbia. Colpire un bersaglio con Mangle (Cat) o Artigliata ha una probabilità del $N3% di azzerare il tempo di recupero di Furia della Tigre.", nil, 0xbf6a19c8, nil, "um" },
  [431447] = { "Incidi sul tuo elmo la runa Sbudellamento:\n\n$I1\nColpire un bersaglio con Lacerazione, Spazzata o Zampata ha una probabilità del $N1% di azzerare il tempo di recupero di Mangle (Bear) e di fornire $N2 rabbia. Colpire un bersaglio con Mangle (Cat) o Artigliata ha una probabilità del $N3% di azzerare il tempo di recupero di Furia della Tigre.", nil, 0x744cbcf4, nil, "um" },
  [431448] = { "Ottieni l'abilità Pelledura Migliorata:\n\n$I1\nPelledura ora può essere lanciata sugli alleati, non penalizza più la velocità di combattimento in mischia né il tempo di lancio degli incantesimi e può essere lanciata in forma trasformata.", nil, 0xf905a951, nil, "um" },
  [431449] = { "Incidi sul tuo elmo la runa Pelledura Migliorata:\n\n$I1\nPelledura ora può essere lanciata sugli alleati, non penalizza più la velocità di combattimento in mischia né il tempo di lancio degli incantesimi e può essere lanciata in forma trasformata.", nil, 0x313924c7, nil, "um" },
  [431450] = { "Ottieni l'abilità Venti Impetuosi:\n\n$I1\nAumenta del $N1% i danni inflitti da Uragano, che non ha più tempo di recupero, e ne riduce il costo in mana del $N2%.", nil, 0x2a12fdde, nil, "um" },
  [431451] = { "Incidi sul tuo elmo la runa Venti Impetuosi:\n\n$I1\nAumenta del $N1% i danni inflitti da Uragano, che non ha più tempo di recupero, e ne riduce il costo in mana del $N2%.", nil, 0x1daa8dad, nil, "um" },
  [431458] = { "Ottieni l'abilità Improved Frenzied Regeneration:\n\n$I1\n⟦Frenzied Regeneration=Rigenerazione Furiosa⟧ ora può essere usata in tutte le forme tranne Forma di Lunagufo e la forma normale. Ora converte la tua risorsa attiva in salute ogni secondo per $D1. Ogni secondo vengono convertiti fino a $N2 rabbia, $N3 energia o il $N4% del mana di base in fino al $N5% di salute.", nil, 0x9f60bb24, nil, "um" },
  [431461] = { "Incidi sui tuoi bracciali la runa Improved Frenzied Regeneration:\n\n$I1\n⟦Frenzied Regeneration=Rigenerazione Furiosa⟧ ora può essere usata in tutte le forme tranne Forma di Lunagufo e la forma normale. Ora converte la tua risorsa attiva in salute ogni secondo per $D1. Ogni secondo vengono convertiti fino a $N2 rabbia, $N3 energia o il $N4% del mana di base in fino al $N5% di salute.", nil, 0x7c8d070b, nil, "um" },
  [431466] = { "Ottieni l'abilità Efflorescenza:\n\n$I1\nGuarigione Immediata ora causa anche Efflorescenza, che cura tutti i membri del gruppo entro $N1 m dal punto in cui si trova il bersaglio di Guarigione Immediata di $N2 ogni $D1 per $D2.", nil, 0xdf1ff38f, nil, "um" },
  [431468] = { "Incidi sui tuoi bracciali la runa Efflorescenza:\n\n$I1\nGuarigione Immediata ora causa anche Efflorescenza, che cura tutti i membri del gruppo entro $N1 m dal punto in cui si trova il bersaglio di Guarigione Immediata di $N2 ogni $D1 per $D2.", nil, 0x666a61dd, nil, "um" },
  [431600] = { "Ottieni l'abilità Focalizzazione:\n\n$I1\nConsuma tutte le applicazioni di Frenesia del tuo famiglio, aumentando la tua velocità d'attacco a distanza del $N1% e fornendo al famiglio $N2 Focus per ogni applicazione di Frenesia consumata. Dura $D1.\n\nIl tuo famiglio ottiene Frenesia ogni volta che usa un attacco base, che aumenta la sua velocità d'attacco in mischia del $N4% per $D2, cumulabile fino a $N6 volte.", nil, 0xc16deb3c, nil, "um" },
  [431601] = { "Incidi sui tuoi bracciali la runa Focalizzazione:\n\n$I1\nConsuma tutte le applicazioni di Frenesia del tuo famiglio, aumentando la tua velocità d'attacco a distanza del $N1% e fornendo al famiglio $N2 Focus per ogni applicazione di Frenesia consumata. Dura $D1.\n\nIl tuo famiglio ottiene Frenesia ogni volta che usa un attacco base, che aumenta la sua velocità d'attacco in mischia del $N4% per $D2, cumulabile fino a $N6 volte.", nil, 0x402ff8e0, nil, "um" },
  [431606] = { nil, "Aumenta la velocità d'attacco in mischia del famiglio del $N1%.", nil, 0x389c7132, "mu" },
  [431610] = { "Ottieni l'abilità T.N.T.:\n\n$I1\nAumenta del $N1% i danni inflitti da Tiro Esplosivo e da tutte le tue trappole che infliggono danni. Inoltre, i danni iniziali di Trappola Esplosiva e i danni periodici totali di Trappola Incendiaria aumentano di un ammontare pari al $N2% della tua potenza d'attacco in mischia o a distanza.", nil, 0x9be068df, nil, "um" },
  [431611] = { "Incidi sui tuoi bracciali la runa T.N.T.:\n\n$I1\nAumenta del $N1% i danni inflitti da Tiro Esplosivo e da tutte le tue trappole che infliggono danni. Inoltre, i danni iniziali di Trappola Esplosiva e i danni periodici totali di Trappola Incendiaria aumentano di un ammontare pari al $N2% della tua potenza d'attacco in mischia o a distanza.", nil, 0xfc51a099, nil, "um" },
  [431622] = { "Le tue cure critiche non periodiche creano uno scudo protettivo sul bersaglio che assorbe il $N1% della quantità curata. Lo scudo assorbe fino a $N2 danni e dura $D1.", nil, 0x21d40ec5, nil, "um" },
  [431624] = { "Le cure critiche hanno una probabilità di creare uno scudo protettivo sul bersaglio che assorbe una percentuale della quantità curata. Dura $D1.", "$N1 danni subiti assorbiti.", 0x678718ca, 0x4e7b6db5, "uu" },
  [431649] = { "Ottieni l'abilità Egida Divina:\n\n$I1\nLe tue cure critiche non periodiche creano uno scudo protettivo sul bersaglio che assorbe il $N1% della quantità curata. Lo scudo assorbe fino a $N2 danni e dura $D1.", nil, 0x54666a47, nil, "um" },
  [431650] = { "Incidi sul tuo elmo la runa Egida Divina:\n\n$I1\nLe tue cure critiche non periodiche creano uno scudo protettivo sul bersaglio che assorbe il $N1% della quantità curata. Lo scudo assorbe fino a $N2 danni e dura $D1.", nil, 0xc4df145c, nil, "um" },
  [431655] = { "Colpisce il bersaglio infliggendo $N1 danni da ombragelo e aumenta del $N2% la probabilità di critico della tua prossima ⟦Mind Blast=Detonazione Mentale⟧ sul bersaglio, cumulabile fino a $N3 volte.", nil, 0x6285d513, nil, "um" },
  [431662] = { "Ottieni l'abilità Aculeo Mentale:\n\n$I1\nColpisce il bersaglio infliggendo $N1 danni da ombragelo e aumenta del $N2% la probabilità di critico della tua prossima Detonazione Mentale sul bersaglio, cumulabile fino a $N3 volte.", nil, 0xc8d6f2aa, nil, "um" },
  [431663] = { "Incidi sulla tua cintura la runa Aculeo Mentale:\n\n$I1\nColpisce il bersaglio infliggendo $N1 danni da ombragelo e aumenta del $N2% la probabilità di critico della tua prossima Detonazione Mentale sul bersaglio, cumulabile fino a $N3 volte.", nil, 0xe3ddcdbb, nil, "um" },
  [431664] = { "Gli incantesimi critici rendono istantanea la tua prossima Punizione o ⟦Flash Heal=Cura Rapida⟧ lanciata entro $D1.", nil, 0xdae686de, nil, "um" },
  [431668] = { "Ottieni l'abilità Eruzione di Luce:\n\n$I1\nGli incantesimi critici rendono istantanea la tua prossima Punizione o Cura Rapida lanciata entro $D1.", nil, 0xea12a989, nil, "um" },
  [431669] = { "Incidi sui tuoi bracciali la runa Eruzione di Luce:\n\n$I1\nGli incantesimi critici rendono istantanea la tua prossima Punizione o Cura Rapida lanciata entro $D1.", nil, 0x456d61d2, nil, "um" },
  [431670] = { "I danni periodici dei tuoi incantesimi ora possono essere critici e tutti i colpi critici dei tuoi incantesimi offensivi infliggono il $N1% dei danni.", nil, 0xe90e5100, nil, "um" },
  [431673] = { "Incidi sui tuoi bracciali la runa Disperazione:\n\n$I1\nI danni periodici dei tuoi incantesimi ora possono essere critici e tutti i colpi critici dei tuoi incantesimi offensivi infliggono il $N1% dei danni.", nil, 0xc08da534, nil, "um" },
  [431675] = { "Ottieni l'abilità Disperazione:\n\n$I1\nI danni periodici dei tuoi incantesimi ora possono essere critici e tutti i colpi critici dei tuoi incantesimi offensivi infliggono il $N1% dei danni.", nil, 0xb190fd53, nil, "um" },
  [431681] = { "Evoca una zona del vuoto nell'area bersaglio che infligge $N1 danni da ombra ogni secondo ai nemici al suo interno per $D1.", nil, 0x24120074, nil, "um" },
  [431704] = { "Ottieni l'abilità ⟦Void Zone=Zona del Vuoto⟧:\n\n$I1\nEvoca una zona del vuoto nell'area bersaglio che infligge $N1 danni da ombra ogni secondo ai nemici al suo interno per $D1.", nil, 0x507d1aec, nil, "um" },
  [431705] = { "Incidi sui tuoi bracciali la runa ⟦Void Zone=Zona del Vuoto⟧:\n\n$I1\nEvoca una zona del vuoto nell'area bersaglio che infligge $N1 danni da ombra ogni secondo ai nemici al suo interno per $D1.", nil, 0xde4479c0, nil, "um" },
  [431742] = { "Ottieni l'abilità Ritorno di Fiamma:\n\n$I1\nConflagrazione fornisce anche il $N1% di celerità nel lancio degli incantesimi per $D1 e non consuma più Immolazione.", nil, 0x0f926fd1, nil, "um" },
  [431743] = { "Incidi sul tuo elmo la runa Pandemia:\n\n$I1\nAumenta del $N1% il bonus ai danni critici di Corruzione, Bane of Agony, Anatema della Rovina, Risucchio d'Anima, Risucchio di Vita, Aspirazione della Vita e Wrack.", nil, 0xfc32fa36, nil, "um" },
  [431745] = { "Incidi sul tuo elmo la runa Ritorno di Fiamma:\n\n$I1\nConflagrazione fornisce anche il $N1% di celerità nel lancio degli incantesimi per $D1 e non consuma più Immolazione.", nil, 0x85225ee1, nil, "um" },
  [431747] = { "Incidi sui tuoi bracciali la runa Afflizione Instabile:\n\n$I1\nL'energia d'ombra distrugge lentamente il bersaglio, infliggendo $N1 danni in $D1. Inoltre, se Afflizione Instabile viene dissolta, infligge $N3 danni a chi la dissolve e lo silenzia per $D2. Su un bersaglio può essere attiva una sola Afflizione Instabile o Immolazione per Stregone.", nil, 0xfe30632b, nil, "um" },
  [431748] = { "Ottieni l'abilità Afflizione Instabile:\n\n$I1\nL'energia d'ombra distrugge lentamente il bersaglio, infliggendo $N1 danni in $D1. Inoltre, se Afflizione Instabile viene dissolta, infligge $N3 danni a chi la dissolve e lo silenzia per $D2. Su un bersaglio può essere attiva una sola Afflizione Instabile o Immolazione per Stregone.", nil, 0xcde0fe67, nil, "um" },
  [431754] = { "Ottieni l'abilità Evocazione: Vilguardia:\n\n$I1\nEvoca una vilguardia al comando dello Stregone.\n\nLa vilguardia beneficia di tutti i talenti e gli effetti che si attivano dagli altri tuoi servitori demoniaci o che li potenziano.", nil, 0xb7f6c829, nil, "um" },
  [431756] = { "Incidi sui tuoi bracciali la runa Evocazione: Vilguardia:\n\n$I1\nEvoca una vilguardia al comando dello Stregone.\n\nLa vilguardia beneficia di tutti i talenti e gli effetti che si attivano dagli altri tuoi servitori demoniaci o che li potenziano.", nil, 0x2f46ea21, nil, "um" },
  [431757] = { "Ottieni l'abilità Rogo Rovente:\n\n$I1\nUstiona i nemici vicini infliggendo $N1 danni ogni volta che un nemico ti attacca in mischia (non più di una volta al secondo), riduce tutti i danni magici subiti del $N2% e aumenta i danni da fuoco inflitti del $N3%. Dura $D1.", nil, 0xc84e8944, nil, "um" },
  [431758] = { "Incidi sui tuoi bracciali la runa Rogo Rovente:\n\n$I1\nUstiona i nemici vicini infliggendo $N1 danni ogni volta che un nemico ti attacca in mischia (non più di una volta al secondo), riduce tutti i danni magici subiti del $N2% e aumenta i danni da fuoco inflitti del $N3%. Dura $D1.", nil, 0xb234c15a, nil, "um" },
  [431839] = { nil, "Gli effetti di respinta sono più efficaci su di te!", nil, 0x66406e4b, "mu" },
